begin;
do $$ begin create type public.quotation_status as enum ('draft','received','under_review','accepted','rejected','superseded','archived'); exception when duplicate_object then null; end $$;
create table public.quotations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),rfq_id uuid not null,rfq_item_id uuid not null,supplier_id uuid not null,supplier_candidate_id uuid not null,supplier_request_id uuid references public.supplier_requests(id) on delete set null,supplier_response_id uuid references public.supplier_responses(id) on delete set null,quotation_reference text not null check(quotation_reference~'^[A-Z0-9-]{3,80}$'),version_number integer not null check(version_number>0),status public.quotation_status not null default 'draft',currency text not null check(currency~'^[A-Z]{3}$'),quotation_date date not null default current_date,valid_until date,payment_terms text,incoterm text check(incoterm is null or incoterm~'^[A-Z]{3}$'),lead_time_days integer check(lead_time_days is null or lead_time_days>=0),moq numeric(18,3) check(moq is null or moq>0),supplier_notes text,internal_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz,unique(supplier_candidate_id,version_number),unique(id,organization_id),foreign key(rfq_item_id,organization_id) references public.rfq_items(id,organization_id),foreign key(supplier_id,organization_id) references public.suppliers(id,organization_id),foreign key(supplier_candidate_id,organization_id) references public.supplier_candidates(id,organization_id),check(valid_until is null or valid_until>=quotation_date),check((status='archived')=(archived_at is not null)));
create table public.quotation_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null,quotation_id uuid not null,rfq_item_id uuid not null,quantity numeric(18,3) not null check(quantity>0),unit text not null check(char_length(trim(unit)) between 1 and 40),unit_price numeric(18,3) not null check(unit_price>=0),total_price numeric(18,3) generated always as(quantity*unit_price) stored,moq numeric(18,3) check(moq is null or moq>0),packaging_info text,lead_time_days integer check(lead_time_days is null or lead_time_days>=0),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(quotation_id,organization_id) references public.quotations(id,organization_id),foreign key(rfq_item_id,organization_id) references public.rfq_items(id,organization_id));
create trigger quotations_updated before update on public.quotations for each row execute procedure public.set_updated_at();create trigger quotation_items_updated before update on public.quotation_items for each row execute procedure public.set_updated_at();
create or replace function public.is_quotation_manager(org uuid) returns boolean language sql stable security definer set search_path=public as $$select public.has_active_organization_role(org,array['owner','admin','operations','purchasing']::public.app_role[])$$;create or replace function public.is_quotation_reader(org uuid) returns boolean language sql stable security definer set search_path=public as $$select public.has_active_organization_role(org,array['owner','admin','operations','purchasing','inspection','finance']::public.app_role[])$$;
alter table public.quotations enable row level security;alter table public.quotation_items enable row level security;revoke all on public.quotations,public.quotation_items from anon,authenticated;grant select,update on public.quotations to authenticated;grant select,insert,update on public.quotation_items to authenticated;create policy "quotation read" on public.quotations for select to authenticated using(public.is_quotation_reader(organization_id));create policy "quotation update" on public.quotations for update to authenticated using(public.is_quotation_manager(organization_id)) with check(public.is_quotation_manager(organization_id));create policy "quotation item read" on public.quotation_items for select to authenticated using(public.is_quotation_reader(organization_id));create policy "quotation item insert" on public.quotation_items for insert to authenticated with check(public.is_quotation_manager(organization_id));create policy "quotation item update" on public.quotation_items for update to authenticated using(public.is_quotation_manager(organization_id)) with check(public.is_quotation_manager(organization_id));
commit;
